#!/usr/bin/env node
import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { readFile, writeFile, appendFile } from 'node:fs/promises';

const ROOT = '/Volumes/fast/Github/oddspark';
const PACKET = `${ROOT}/_bmad-output/implementation-artifacts/production-key-pin-deployment-packet-2026-02-r7.json`;
const EVIDENCE = `${ROOT}/_bmad/memory/agent-project-governor/harness-sessions/production-key-pin-deployment-r7-execution-evidence.json`;
const HANDOFF = `${ROOT}/_bmad/memory/agent-project-governor/harness-sessions/production-key-pin-deployment-r7-execution-handoff.md`;
const sha = b => createHash('sha256').update(b).digest('hex');
const now = () => new Date().toISOString();
const packetBytes = await readFile(PACKET);
const packet = JSON.parse(packetBytes);
const scriptBytes = Buffer.from(packet.machine_runner.embedded_script, 'utf8');
if (sha(scriptBytes) !== packet.machine_runner.embedded_script_sha256) throw new Error('embedded runner hash mismatch');
for (const key of ['APPROVED_PACKET_SHA256','APPROVAL_RECORD_PATH','APPROVAL_TEXT_SHA256']) if (!process.env[key]) throw new Error(`missing ${key}`);

const resolveEntry = item => {
  const section = packet[item.section];
  const entry = Array.isArray(section) ? section.find(x => x?.name === item.name) : section;
  if (!entry) throw new Error(`unresolved ordinal ${item.ordinal}`);
  return entry;
};
const record = {status:'RUNNING', initialized_at:now(), external_binding:{approved_packet_sha256:process.env.APPROVED_PACKET_SHA256,approval_record_path:process.env.APPROVAL_RECORD_PATH,approval_text_sha256:process.env.APPROVAL_TEXT_SHA256,packet_sha256_recomputed_before_ordinal_1:sha(packetBytes)},commands:[],new_version_id_or_null:null,boundary_counts:{cloudflare_observation_invocations:0,smoke_get_invocations:0,tail_parent_invocations:0,tail_child_invocations:0,served_metric_writes_upper_bound:0,kv_projection_repair_writes_upper_bound:0,provider_calls:0,signing_operations:0,activation_operations:0,rollback_operations:0}};
await writeFile(EVIDENCE, JSON.stringify(record,null,2)+'\n',{mode:0o600});

const run = (command, env) => new Promise((resolve,reject) => {
  const child = spawn('/bin/bash',['-c',command],{cwd:ROOT,env,stdio:['ignore','pipe','pipe']});
  const out=[], err=[];
  child.stdout.on('data',b=>out.push(b)); child.stderr.on('data',b=>err.push(b));
  child.on('error',reject); child.on('close',(code,signal)=>resolve({code,signal,stdout:Buffer.concat(out),stderr:Buffer.concat(err)}));
});
const exactEmpty = r => r.code===0 && r.stdout.length===0 && r.stderr.length===0;
const parse = (ordinal, entry, result) => {
  const text = result.stdout.toString('utf8'), err = result.stderr.toString('utf8');
  if (ordinal <= 9) return exactEmpty(result);
  if (result.code !== 0) return false;
  if (ordinal===10) return text.includes('writer preflight passed') && text.includes('assembly:verify') && text.includes('0eca7833bf857403949928960f2975116445e593471d5c84c9e47499657318e6');
  if (ordinal===11) { const names=[...text.matchAll(/^\s*-\s+([A-Z][A-Z0-9_]*)\b/gm)].map(m=>m[1]).sort(); return JSON.stringify(names)===JSON.stringify(packet.binding_invariants.expected_bindings_sorted) && !/ACTIVATION_(SNAPSHOT|MANIFEST)|Current Version ID|Uploaded|Deployed|warning/i.test(text+err); }
  if ([12,13,15,16,17].includes(ordinal)) { try { JSON.parse(text); return true; } catch { return false; } }
  if (ordinal===14) { const ids=[...text.matchAll(/^Current Version ID: ([0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12})$/gm)].map(m=>m[1]); if(ids.length!==1||ids[0]===packet.deployment.predecessor_version_id)return false; record.new_version_id_or_null=ids[0]; return true; }
  if ([18,19,20].includes(ordinal)) return /^200\n/.test(text);
  if (ordinal===21) return !/unauthorized|forbidden|failed to create tail|connection.*(?:closed|failed)/i.test(err);
  return false;
};

let failed=null;
for (const item of packet.ordered_retained_command_inventory) {
  const entry=resolveEntry(item); let command=entry.command ?? entry.command_template;
  if (command.includes('$NEW_VERSION_ID') && !record.new_version_id_or_null) throw new Error(`ordinal ${item.ordinal} missing NEW_VERSION_ID`);
  const env={...process.env,NEW_VERSION_ID:record.new_version_id_or_null ?? ''};
  const started=now(); const result=await run(command,env); const ended=now();
  const row={ordinal:item.ordinal,section:item.section,command_name:item.name,literal_command:command,parser:entry.parser,invocation_count:1,wait_poll_count:0,started_at:started,ended_at:ended,terminal_exit:result.code,terminal_signal:result.signal,stdout_sha256:sha(result.stdout),stderr_sha256:sha(result.stderr),stdout_bytes:result.stdout.length,stderr_bytes:result.stderr.length,stdout_utf8:result.stdout.toString('utf8'),stderr_utf8:result.stderr.toString('utf8'),retained_file_paths_and_sha256:[],parser_result:'FAIL'};
  if ([12,13,15,16,17].includes(item.ordinal)) record.boundary_counts.cloudflare_observation_invocations++;
  if ([18,19,20].includes(item.ordinal)) record.boundary_counts.smoke_get_invocations++;
  if (item.ordinal===21) { record.boundary_counts.tail_parent_invocations=1; record.boundary_counts.tail_child_invocations=1; }
  row.parser_result=parse(item.ordinal,entry,result)?'PASS':'FAIL'; record.commands.push(row);
  await writeFile(EVIDENCE,JSON.stringify(record,null,2)+'\n',{mode:0o600});
  if(row.parser_result!=='PASS'){failed=item.ordinal;break;}
}
record.status=failed===null?'COMPLETE':'STOPPED_ON_RETAINED_COMMAND_FAILURE'; record.failed_or_ambiguous_ordinal_or_null=failed; record.later_ordinals_invoked_must_be_zero=failed===null?0:21-failed;
await writeFile(EVIDENCE,JSON.stringify(record,null,2)+'\n',{mode:0o600});
await writeFile(HANDOFF,`# Oddspark production key-pin deployment r7 execution handoff\n\n- status: ${record.status}\n- failed_or_ambiguous_ordinal: ${failed ?? 'null'}\n- last_invoked_ordinal: ${record.commands.at(-1)?.ordinal ?? 0}\n- evidence: ${EVIDENCE}\n`,{mode:0o600});
process.exit(failed===null?0:1);
